from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.64.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.64.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
APP=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.64.0.js').read_text()
CSS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.64.0.css').read_text()
COMPAT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-browser-compatibility-v1.js').read_text()
A11Y=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-accessibility-v1.js').read_text()
A11YUI=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-accessibility-ui-v1.js').read_text()
INTEGRITY=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-persistence-integrity-v1.js').read_text()
NAV=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-navigation-v1.js').read_text()
EXP=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-experience-v1.js').read_text()
def check(ok,label):
    if not ok: raise SystemExit('FAIL - '+label)
check('Version: 0.64.0' in MAIN and "SC_WORKSPACE_VERSION', '0.64.0" in MAIN,'plugin version')
check((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.64.0','0.63.0','Accessibility & Keyboard-First Product Audit'),'release lineage')
check(MAN['storage_schema_version']==35 and MAN['project_schema']=='sc-workspace-project/20.0' and MAN['schema_migration_required'] is False,'schema stable')
check('/wp-json/sc-workspace/v1/accessibility-contract' in MAN['rest_routes'],'accessibility REST manifest')
check("'/accessibility-contract'" in PHP and 'accessibility_contract' in PHP,'accessibility REST implementation')
check('data-scw-workspace-view="accessibility"' in PHP and 'data-scw-workspace-section="accessibility"' in PHP,'Accessibility UI route')
check("SCHEMA='sc-workspace-accessibility/1.0'" in A11Y and "REPORT_SCHEMA='sc-workspace-accessibility-report/1.0'" in A11Y and "CHECKLIST_SCHEMA='sc-workspace-accessibility-checklist/1.0'" in A11Y,'accessibility schemas')
check("const TARGET='WCAG 2.2 AA'" in A11Y and 'automatedCertification:false' in A11Y and 'manualAuditRequired:true' in A11Y,'claim boundary')
check('wireKeyboardGroup' in A11Y and 'ArrowLeft' in A11Y and 'Home' in A11Y and 'End' in A11Y,'keyboard navigation')
check('containTab' in A11Y and 'installDialogGuard' in A11Y and "event.key==='Escape'" in A11Y,'dialog focus containment')
check('dialogOpener=document.activeElement' in EXP,'dialog opener restoration')
check('projectContentIncluded:false' in A11Y and 'sourceContentIncluded:false' in A11Y and 'rawUserAgentIncluded:false' in A11Y and 'deviceIdentifierIncluded:false' in A11Y,'privacy minimized report')
check('keyboard-complete' in A11Y and 'screen-reader-voiceover' in A11Y and 'screen-reader-windows' in A11Y and 'reflow-400' in A11Y,'manual checklist')
check('helper.enhance(root,window)' in A11YUI and 'helper.audit(root,window)' in A11YUI and 'helper.checklist()' in A11YUI,'accessibility UI runtime')
check("accessibility:'Accessibility'" in NAV and "'integrity','compatibility','accessibility'" in NAV,'navigation map')
check("root.querySelectorAll('[data-scw-workspace-section]').forEach(section => { section.hidden = section.dataset.scwWorkspaceSection !== workspaceView; });" in APP,'normalized route visibility')
check("id:'accessibility'" in EXP,'command palette accessibility route')
check(':focus-visible{outline:3px solid currentColor!important' in CSS and '@media(prefers-reduced-motion:reduce)' in CSS and '@media(forced-colors:active)' in CSS,'accessibility CSS')
check('sc-workspace-accessibility-v1.js' in PHP and 'sc-workspace-accessibility-ui-v1.js' in PHP,'accessibility assets enqueued')
check('workspace-v0.64.0.js' in PHP and 'workspace-v0.64.0.css' in PHP and len(APP)>100000,'current assets')
# Prior hardening remains intact.
check("SCHEMA='sc-workspace-browser-compatibility/1.0'" in COMPAT and 'featureDetectionPrimary:true' in COMPAT and 'userAgentGating:false' in COMPAT,'v0.63 compatibility preserved')
check("METADATA_KEY='sc_workspace_persistence_integrity_v0620'" in INTEGRITY and "TRANSACTION_KEY='sc_workspace_persistence_txn_v0620'" in INTEGRITY,'v0.62 integrity preserved')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0640'" in REGPHP and 'LEGACY_PENDING_KEY_V0630' in REGPHP,'registry recovery')
check(REG['public_version']=='0.64.0' and REG['previous_version']=='0.63.0','registry record')
for n in ['sc-workspace-accessibility-v1.schema.json','sc-workspace-accessibility-report-v1.schema.json','sc-workspace-accessibility-checklist-v1.schema.json']:
    json.loads((ROOT/'schemas'/n).read_text())
check((ROOT/'history/release-manifest-v0.63.0.json').exists() and (ROOT/'history/workspace-product-record-v0.63.0.json').exists(),'predecessor history')
check(MAN['accessibility_keyboard_audit']['manual_audit_required'] is True and MAN['accessibility_keyboard_audit']['automated_certification'] is False,'manual accessibility QA boundary')
check(PHP.count('A free project environment for carrying questions, evidence, data, analysis, decisions, and authored work across Sustainable Catalyst.')==1,'duplicate hero deck remains removed')
print('PASS - v0.64.0 release validator')
